import{_ as a,c as r,o as n,ag as c}from"./chunks/framework.DPDPlp3K.js";const e="/assets/attribute-stock-basic.CwURHjul.png",l="/assets/attribute-stock-basic@2x.Nt35pr2f.png",o="/assets/attribute-stock-items.DiDkwwLn.png",u="/assets/attribute-stock-items@2x.DEerv-rM.png",i="/assets/attribute-stock-edit.C_eV6oX8.png",d="/assets/attribute-stock-edit@2x.B2fdlyFr.png",s="/assets/attribute-stock-export.BKk716KR.png",h="/assets/attribute-stock-export@2x.D6Vb_Syq.png",q=JSON.parse('{"title":"Attribute Stock","description":"","frontmatter":{},"headers":[],"relativePath":"attribute-stock.md","filePath":"attribute-stock.md"}'),p={name:"attribute-stock.md"},m=e+", "+l+" 2x",b=o+", "+u+" 2x",g=i+", "+d+" 2x",k=s+", "+h+" 2x";function f(y,t,w,_,v,x){return n(),r("div",null,t[0]||(t[0]=[c('<h1 id="attribute-stock" tabindex="-1">Attribute Stock <a class="header-anchor" href="#attribute-stock" aria-label="Permalink to &quot;Attribute Stock&quot;">​</a></h1><p>Attribute stock is a new type of stock that exists separately from <a href="./terminology#product-stock">product stock</a>. Because this stock isn&#39;t bound to product listings like normal product stock, it can be used across different products or product variations.</p><p>Attribute stock and product stock can be used at the same time; they&#39;re not mutually exclusive. However, it&#39;s common to disable stock on your product listings and use attribute stock exclusively, to keep everything in one place.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><p>The most basic form of attribute stock is to enable stock management directly on an <a href="./terminology#attribute-term">attribute term</a>. Stock will be used accordingly by all products with this attribute term.</p><p><img src="'+e+'" alt="Attribute term stock" srcset="'+m+'" width="1300" height="604"></p><h2 id="attribute-stock-items" tabindex="-1">Attribute stock items <a class="header-anchor" href="#attribute-stock-items" aria-label="Permalink to &quot;Attribute stock items&quot;">​</a></h2><p>When enabling stock on an attribute/term, a new <a href="./terminology#attribute-stock-item">attribute stock item</a> is automatically created. These stock items are the building blocks of attribute stock. Each stock item represents a single inventory and allows configuring a wide range of options and rules.</p><p><img src="'+o+'" alt="Attribute stock items" srcset="'+b+'" width="1300" height="480"></p><p>The Attribute Stock screen is a full-featured stock management interface for your attribute stock. Whether you enable stock on attributes, or create attribute stock items directly, your stock can be easily viewed and updated from this screen.</p><h2 id="configuring-attribute-stock" tabindex="-1">Configuring attribute stock <a class="header-anchor" href="#configuring-attribute-stock" aria-label="Permalink to &quot;Configuring attribute stock&quot;">​</a></h2><p>Attribute stock items provide a number of different configuration options, making them extremely flexible for even the most complex stock setups.</p><p><img src="'+i+'" alt="Attribute stock item edit" srcset="'+g+'" width="1300" height="712"></p><h3 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h3><ul><li><strong>SKU</strong> — Set an optional <em>Stock Keeping Unit</em> for the stock item. This is for your own reference and doesn&#39;t affect stock functionality in any way.</li><li><strong>Stock quantity</strong> — The current stock quantity of the stock item. Can also be decimal or negative.</li><li><strong>Notes</strong> — Internal notes about the stock item for your own reference.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong>Low stock threshold</strong> — When stock drops to this amount or below, you&#39;ll be notified by email (if enabled in WooCommerce settings). Stock quantities below this threshold will be displayed in red on the attribute stock item list screen.</li><li><strong>Allow backorders</strong> — Allow or disallow backorders on matched products that do not have stock management enabled. Defaults to the global &quot;Allow backorders&quot; setting.</li><li><strong>Internal stock</strong> — An internal stock item will be ignored when determining the available stock of matched products. In other words, it won&#39;t affect a product&#39;s stock level, be displayed on the product page, or prevent over-purchasing.</li><li><strong>Multiplex matching</strong> — With this option enabled, stock will be deducted for <em>every matching attribute rule</em> in cases when more than one match occurs for a product/variation. This is an alternative to the default of only reducing stock for the <em>first matching attribute rule</em>.</li><li><strong>Lock multipliers</strong> — By default, if you set a stock multiplier on an associated product, it will be used instead of the multiplier of the stock item. Enable this option to always use the stock item&#39;s multiplier regardless of a product&#39;s own stock multiplier value.</li><li><strong>Product SKU</strong> — Enable this option to use the stock item&#39;s SKU as the product SKU for products/variations that don&#39;t have an SKU set.</li><li><strong>Product image</strong> — Enable this option to use the stock item&#39;s image as the product image for products/variations that don&#39;t have an image set.</li></ul><h2 id="match-rules" tabindex="-1">Match rules <a class="header-anchor" href="#match-rules" aria-label="Permalink to &quot;Match rules&quot;">​</a></h2><p>Match rules are where you define the <a href="./terminology#match-rule-conditions">conditions</a> to match the stock item to products. Each rule can include any combination of products, attributes, or both. Rules can also set an optional <a href="./stock-multipliers#attribute-stock-multipliers">stock multiplier</a>.</p><p>Match rules are queried <strong>from top to bottom</strong> and require a product/variation to match <strong>all conditions</strong> in a rule to be associated with the stock item.</p><p>Conditions with multiple values only require products to match <strong>one of</strong> the selected values in the condition (OR relationship).</p><p>Additionally, several filters can be set to narrow down the products that an attribute stock item will apply to:</p><ul><li><strong>Products</strong> — Filter matches to only the specified products (<em>prefer using product conditions in match rules</em>).</li><li><strong>Exclude products</strong> — Filter matches to all products except the specified products.</li><li><strong>Categories</strong> — Filter matches to only products in the specified categories.</li><li><strong>Exclude categories</strong> — Filter matches to products in all but the specified categories.</li><li><strong>Product types</strong> — Filter matches to only products of the specified type.</li></ul><h2 id="importing-exporting" tabindex="-1">Importing &amp; Exporting <a class="header-anchor" href="#importing-exporting" aria-label="Permalink to &quot;Importing &amp; Exporting&quot;">​</a></h2><p>An important feature on the Attribute Stock dashboard is importing and exporting to/from CSV. It is especially useful when adding or updating a large number of stock items in bulk, as it can be much faster to do in a spreadsheet editor like Excel or Google Sheets.</p><p><img src="'+s+'" alt="Attribute stock export" srcset="'+k+'" width="1282" height="292"></p><p>Exporting your stock data to CSV also helps to spot mistakes in your configuration more easily. And it doubles as a quick and effective stock report.</p><p>When importing a CSV file, it will attempt to match rows to your current stock items by <code>Title</code> or <code>SKU</code>. If a match is found, the stock item will be updated. Otherwise a new stock item will be created. You can also remove columns from the CSV file if you only want to update specific column data.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To guard against accidental data loss, blank column values will be skipped instead of deleting data for matching stock items. Simply set a cell&#39;s value to <code>[]</code> or <code>()</code> if you want it to be removed.</p></div><h2 id="shortcode" tabindex="-1">Shortcode <a class="header-anchor" href="#shortcode" aria-label="Permalink to &quot;Shortcode&quot;">​</a></h2><p>Sometimes it&#39;s useful to display attribute stock levels on arbitrary pages or areas of your site. To do this more easily we&#39;ve included a simple <a href="https://codex.wordpress.org/Shortcode" target="_blank" rel="noreferrer">shortcode</a> that you can use in one of the following ways:</p><ul><li><code>[attribute_stock id=555]</code></li><li><code>[attribute_stock sku=&quot;ABC123&quot;]</code></li><li><code>[attribute_stock title=&quot;My Stock Item&quot;]</code></li></ul>',32)]))}const A=a(p,[["render",f]]);export{q as __pageData,A as default};
